    acquireStartedAt: 0,
    waypointIdx: 0,
    disengageUntil: 0,
    lastFireAttemptMs: 0,
    recentlyDamagedBy: new Map(),
    lastAcquiringBroadcastMs: 0,
  };
  map.set(ai.id, fresh);
  return fresh;
}

